// k46 断面図から出来事の順番を読む
type Pt = [number, number];
const clipY = (pts: Pt[], y0: number, y1: number): Pt[] => {
  const cut = (poly: Pt[], inside: (p: Pt) => boolean, isect: (a: Pt, b: Pt) => Pt): Pt[] => {
    const out: Pt[] = [];
    for (let i = 0; i < poly.length; i++) {
      const a = poly[i]; const b = poly[(i + 1) % poly.length];
      if (inside(a)) { out.push(a); if (!inside(b)) out.push(isect(a, b)); } else if (inside(b)) out.push(isect(a, b));
    }
    return out;
  };
  const at = (y: number) => (a: Pt, b: Pt): Pt => [a[0] + ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]), y];
  return cut(cut(pts, (p) => p[1] >= y0, at(y0)), (p) => p[1] <= y1, at(y1));
};
const dip = (b: number, x: number): number => b - 0.2 * (x - 20);
const layerPoly = (b1: number, b2: number): Pt[] => clipY([[20, dip(b1, 20)], [300, dip(b1, 300)], [300, dip(b2, 300)], [20, dip(b2, 20)]], 76, 150);
const k46Tilt = (): DiagramElement[] => [
  pg(layerPoly(76, 100), C.main, FILL.warm), pg(layerPoly(100, 124), C.main, FILL.yellow), pg(layerPoly(124, 400), C.gray, FILL.gray),
  lb(62, 84, 'C 石灰岩', 9, C.ink, 'middle', true), lb(62, 108, 'B 砂岩', 9, C.ink, 'middle', true), lb(220, 118, 'A 泥岩', 10, C.ink, 'middle', true),
];
